#!/bin/bash
# Write the images generated by holybro-build-image.sh to the board.
# This is the only step that uses the board over USB.
# The recovery USB link must be 480 Mbps when this starts.
#
# Usage, with the carrier REC switch on:
#   holybro-flash-image.sh [-w DIR]
#     -w DIR  work directory used by holybro-build-image.sh
#             (default: WORK_DIR, else the current directory)

set -euo pipefail

WORK_DIR="${WORK_DIR:-$(pwd)}"
args=("$@")
while [[ $# -gt 0 ]]; do
	case "$1" in
		-w) WORK_DIR="${2:?-w needs a directory}"; shift ;;
		-h|--help) sed -n '2,9p' "$0"; exit 0 ;;
		*) echo "unknown option: $1" >&2; exit 2 ;;
	esac
	shift
done

WORK_DIR="$(cd "$WORK_DIR" && pwd)"
L4T="${WORK_DIR}/Linux_for_Tegra"

if [[ ! -f "${L4T}/tools/kernel_flash/images/external/system.img" ]]; then
	echo "Flash images are missing in ${L4T}." >&2
	echo "Run holybro-build-image.sh -w ${WORK_DIR} first, or pass the right directory with -w." >&2
	exit 1
fi

if [[ "$(id -u)" -ne 0 ]]; then
	exec sudo WORK_DIR="$WORK_DIR" bash "$0" "${args[@]}"
fi

cd "$L4T"
echo 2048 > /sys/module/usbcore/parameters/usbfs_memory_mb
echo -1 > /sys/module/usbcore/parameters/autosuspend

apx_dir=""
apx_speed=""
for vendor in /sys/bus/usb/devices/*/idVendor; do
	[[ -f "$vendor" ]] || continue
	[[ "$(cat "$vendor")" == "0955" ]] || continue
	dir="$(dirname "$vendor")"
	prod="$(cat "${dir}/idProduct")"
	case "$prod" in
		7323|7423|7523|7623)
			apx_dir="$dir"
			apx_speed="$(cat "${dir}/speed")"
			echo on > "${dir}/power/control" 2>/dev/null || true
			echo -1 > "${dir}/power/autosuspend_delay_ms" 2>/dev/null || true
			echo "Found NVIDIA APX 0955:${prod} at $(basename "$dir") speed=${apx_speed}"
			break
			;;
	esac
done

if [[ -z "$apx_dir" || "$apx_speed" != "480" ]]; then
	echo "Need a 480 Mbps recovery device before flashing. speed=${apx_speed:-missing}" >&2
	lsusb -t || true
	exit 1
fi

./tools/kernel_flash/l4t_initrd_flash.sh \
	--flash-only \
	--external-device nvme0n1p1 \
	-c tools/kernel_flash/flash_l4t_t234_nvme.xml \
	-p "-c bootloader/generic/cfg/flash_t234_qspi.xml" \
	--showlogs \
	--network usb0 \
	jetson-orin-nano-devkit-super \
	internal

echo "Flash finished. Power off, move the REC switch to the normal position, then power on."
